"""Restore individually assessed questions at every rating; never infer ratings.

Compact statements below were checked against cached official UKMT papers.
Run after legacy builders, before compile.py. Source/statement holds remain held.
"""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[1]
rows=json.loads((R/'data/british.json').read_text()); cov=json.loads((R/'research/british-coverage.json').read_text())
lookup={f'bmo{s["round"]}-{s["year"]}-q{s["number"]}':s for s in cov['screening']}
lookup.update({f'{s["competition"].lower()}-{s["year"]}-q{s["number"]}':s for s in cov['historicalScreening']})
extra=json.loads((R/'data/bmo-overview-extra.json').read_text())
restored=[]
def q(ident,topic,tags,statement,solution=None,notes=''):
 review=lookup[ident];comp,year,num=ident.split('-');year=int(year);num=num[1:]
 d=review['difficulty'];assert isinstance(d,(int,float)) and 1<=d<=10
 row=dict(id=ident,country='United Kingdom',competition=comp.upper(),year=year,number=num,statement=statement,solution=solution,sourceUrl=f'https://bmos.ukmt.org.uk/home/{comp}-{year}.pdf',solutionUrl=None,topic=topic,tags=tags.split('|'),subtopics=tags.split('|'),difficulty=d,ratingReason=review['reason'],reviewStatus='individually-assessed',notes='Compact mathematical paraphrase checked against the official paper. Individual AI difficulty assessment retained from the review ledger. '+notes)
 siblings=[p for p in rows if p['competition']==comp.upper() and p['year']==year]
 dates={p['sittingDate'] for p in siblings if p.get('sittingDate')}
 if len(dates)==1:row['sittingDate']=next(iter(dates))
 if comp=='bmo1' and year>=2006 or comp=='bmo2' and year>=2024:
  row['solutionUrl']=f'https://bmos.ukmt.org.uk/solutions/{comp}-{year}/'
 if comp=='bmo2' and year in [2021,2022]:
  links={p['solutionUrl'] for p in siblings if p.get('solutionUrl')}
  if len(links)==1:row['solutionUrl']=next(iter(links))
 if ident in extra:row.update({k:extra[ident][k] for k in ['topic','subtopics']})
 if solution:row.update(solutionKind='original-exposition',solutionCredit='Independent mathematical exposition for Olympiad Atlas')
 elif row['solutionUrl']:row['solutionKind']='source-link'
 restored.append(row)

q('bmo1-1992-q1','Number Theory','Digits & bases|Squares & powers',r'Does there exist a two-digit positive integer other than $10,20,30$ whose square has the same number of nonzero decimal digits as the original integer? Give an example or prove impossibility. Answer the analogous question for a three-digit integer other than $100,200,300$.')
q('bmo2-1992-q2','Algebra','Inequalities',r'For positive real numbers $a,b,c,d$, prove $$\frac{12}{a+b+c+d}\le\frac1{a+b}+\frac1{a+c}+\frac1{a+d}+\frac1{b+c}+\frac1{b+d}+\frac1{c+d}\le\frac34\left(\frac1a+\frac1b+\frac1c+\frac1d\right).$$')
q('bmo1-1993-q1','Number Theory','Digits & bases|Squares & powers',r'Find a six-digit perfect square for which the number represented by its final three digits is one greater than the number represented by its first three digits. Explain how you find it.')
q('bmo2-1993-q3','Geometry','Triangle geometry|Trigonometry',r'For an interior point $P$ of triangle $ABC$, put $\alpha=\angle BPC-\angle BAC$, $\beta=\angle CPA-\angle CBA$, and $\gamma=\angle APB-\angle ACB$. Prove $$\frac{PA\sin\angle BAC}{\sin\alpha}=\frac{PB\sin\angle CBA}{\sin\beta}=\frac{PC\sin\angle ACB}{\sin\gamma}.$$')
q('bmo1-1994-q1','Number Theory','Digits & bases|Diophantine equations',r'For a three-digit integer $n$ with digits $a,b,c$, define $f(n)=a+b+c+ab+bc+ca+abc$. Calculate $625/f(625)$, and find every three-digit $n$ such that $n=f(n)$.')
q('bmo1-1994-q2','Geometry','Angle chasing|Triangle geometry',r'In triangle $ABC$, $X$ lies on $BC$. What can you prove about triangle $ACX$ in each of the following cases? (i) $\angle BAC=90^\circ$, $X$ is the midpoint of $BC$, and $\angle BAX=30^\circ$. (ii) $\angle BAC=60^\circ$, $BX=BC/3$, and $AX$ bisects $\angle BAC$.')
q('bmo1-1995-q1','Number Theory','Digits & bases|Modular arithmetic|Squares & powers',r'Find the least positive integer whose square ends in the three digits $444$, and describe all positive integers with this property. Prove that no perfect square ends in $4444$.')
q('bmo1-1996-q2','Algebra','Sequences & recurrences|Telescoping',r'A function on the positive integers satisfies $f(1)=1996$ and $f(1)+\cdots+f(n)=n^2f(n)$ for every $n>1$. Find $f(1996)$ exactly.')
q('bmo1-1996-q5','Algebra','Inequalities',r'For positive real $a,b,c$, prove both $4(a^3+b^3)\ge(a+b)^3$ and $9(a^3+b^3+c^3)\ge(a+b+c)^3$.')
q('bmo2-1996-q2','Geometry','Triangle geometry|Trigonometry',r'Triangles $ABC$ and $UVW$ have opposite side lengths $a,b,c$ and $u,v,w$, respectively, satisfying $$u(v+w-u)=a^2,\quad v(w+u-v)=b^2,\quad w(u+v-w)=c^2.$$ Prove that $ABC$ is acute and express angles $U,V,W$ in terms of $A,B,C$.')
q('bmo2-1996-q3','Geometry','Circles & tangency|Angle chasing',r'Circles $S_1,S_2$ touch externally at $K$ and touch a surrounding circle $S$ internally at $A_1,A_2$, respectively. Let $P$ be an intersection of $S$ with the common tangent at $K$. Let $PA_1$ meet $S_1$ again at $B_1$, and $PA_2$ meet $S_2$ again at $B_2$. Prove that $B_1B_2$ is tangent to both smaller circles.')
q('bmo2-1996-q4','Algebra','Equations & systems|Inequalities',r'Find all positive real quadruples $(a,b,c,d)$ satisfying $$a+b+c+d=12,\qquad abcd=27+ab+ac+ad+bc+bd+cd.$$')
q('bmo1-1997-q1','Number Theory','Digits & bases|Diophantine equations',r'For a four-digit integer $N$ whose final digit is nonzero, let $R(N)$ be the integer obtained by reversing its digits. Determine every $N$ satisfying $R(N)=4N+3$.')
q('bmo1-1997-q2','Algebra','Sequences & recurrences|Telescoping',r'Define $a_1=1$ and $$a_n=\frac{n+1}{n-1}(a_1+\cdots+a_{n-1})\quad(n>1).$$ Find $a_{1997}$.')
q('bmo1-1997-q4','Geometry','Area & dissection|Quadrilaterals & polygons',r'The midpoints of the sides of a convex quadrilateral form a quadrilateral of area $1$. Prove that the original quadrilateral has area $2$.')
q('bmo1-1997-q5','Algebra','Inequalities|Counterexamples',r'Let $x,y,z>0$. Decide, with proof or counterexample, whether each implication is always true: (i) $x+y+z\ge3$ implies $1/x+1/y+1/z\le3$; (ii) $x+y+z\le3$ implies $1/x+1/y+1/z\ge3$.')
q('bmo1-1998-q2','Number Theory','Modular arithmetic|Sequences & recurrences',r'Let $a_1=19$, $a_2=98$, and let $a_{n+2}$ be the remainder of $a_n+a_{n+1}$ on division by $100$. Find the remainder of $a_1^2+\cdots+a_{1998}^2$ on division by $8$.')
q('bmo2-1998-q2','Geometry','Circles & tangency|Angle chasing',r'In triangle $ABC$, $\angle BAC>\angle BCA$. Choose an interior point $P$ with $\angle PAC=\angle BCA$. Construct an exterior point $Q$ such that $PQ\parallel AB$ and $BQ\parallel AC$. Let $R$ lie on $BC$, on the opposite side of $AP$ from $Q$, with $\angle PRQ=\angle BCA$. Prove that the circumcircles of $ABC$ and $PQR$ touch.')
q('bmo1-1999-q2','Geometry','Trigonometry|Circles & tangency',r'A circle has diameter $AB$, and $X$ is fixed strictly between $A$ and $B$. As $P$ varies on the circle, excluding $A,B$, prove that $\tan\angle APX/\tan\angle PAX$ is constant.')
q('bmo2-1999-q2','Geometry','Circles & tangency|Concurrency & collinearity',r'A hexagon $ABCDEF$ circumscribes a circle. The circle touches $AB,CD,EF$ at their respective midpoints $P,Q,R$, and touches $BC,DE,FA$ at $X,Y,Z$. Prove that $PY,QZ,RX$ are concurrent.')
q('bmo1-2001-q5','Geometry','Triangle geometry|Trigonometry',r'A triangle has side lengths $a,b,c$ and circumradius $R$. Prove that it is right-angled if and only if $a^2+b^2+c^2=8R^2$.')
q('bmo1-2002-q1','Number Theory','Diophantine equations|Divisibility & GCD',r'Find every pair of positive integers $m,n$, with $n$ odd, satisfying $1/m+4/n=1/12$.')
q('bmo1-2003-q1','Number Theory','Digits & bases|Valuations|Modular arithmetic',r'In the decimal expansion $$34!=295\,232\,799\,cd9\,604\,140\,847\,618\,609\,643\,5ab\,000\,000,$$ determine the four digits $a,b,c,d$.')
q('bmo1-2003-q3','Algebra','Inequalities',r'Positive real numbers satisfy $x^2+y^2+z^2=1$. Prove that $x^2yz+xy^2z+xyz^2\le1/3$.')
q('bmo2-2003-q1','Number Theory','Primes|Diophantine equations|Sequences & recurrences',r'For $n>1$, let $p(n)$ be its largest prime factor. Determine all triples of distinct positive integers $x,y,z$ in arithmetic progression for which $p(xyz)\le3$.')
q('bmo2-2003-q3','Combinatorics','Permutations & arrangements|Sequences & recurrences',r'Let $f$ be a permutation of the positive integers. (i) Prove that some positive integers $a,d$ satisfy $f(a)<f(a+d)<f(a+2d)$. (ii) Must there exist positive integers $a,d$ such that $f(a)<f(a+d)<\cdots<f(a+2003d)$? Here a permutation means a bijection from the positive integers to themselves.')
q('bmo1-2004-q1','Algebra','Equations & systems|Algebraic identities',r'Find all real solutions of $$ab+c+d=3,\quad bc+d+a=5,\quad cd+a+b=2,\quad da+b+c=6.$$')
q('bmo1-2004-q2','Geometry','Coordinates & vectors|Triangle geometry',r'In rectangle $ABCD$, $P$ is the midpoint of $AB$, and $Q$ is the perpendicular foot from $C$ to line $PD$. Prove that triangle $BQC$ is isosceles.')
q('bmo2-2004-q4','Combinatorics','Sequences & recurrences|Counting',r'A real number $x\in(0,1)$ has decimal expansion $0.a_1a_2\ldots$. Among all consecutive blocks $a_ka_{k+1}\cdots a_{k+2003}$, for $k\ge1$, there are at most $2004$ distinct blocks. Prove that $x$ is rational.')
q('bmo1-2005-q1','Number Theory','Diophantine equations|Divisibility & GCD',r'Paul and Jenny each have a whole number of pounds. Paul says that if Jenny gives him £3, he will have $n$ times her remaining money. Jenny says that if Paul gives her £$n$, she will have three times his remaining money. Determine the possible positive integers $n$ for which both statements can hold.')
q('bmo2-2005-q4','Combinatorics','Sets & partitions|Extremal arguments|Counting',r'A family $X=\{A_1,\ldots,A_n\}$ consists of distinct three-element subsets of $\{1,\ldots,36\}$. Every two members intersect, but the intersection of all members is empty. Prove that $n\le100$, and count the possible families with $n=100$.')
q('bmo1-2006-q1','Number Theory','Primes|Modular arithmetic|Divisibility & GCD',r'Let $n>6$ be an integer. Prove that if $n-1$ and $n+1$ are prime, then $720$ divides $n^2(n^2+16)$. Decide whether the converse holds.')
q('bmo2-2006-q4','Combinatorics','Sets & partitions|Extremal arguments|Counting',r'An examination with six right-or-wrong questions is taken by $2006$ children. For every three children, their combined correct answers cover at least five questions. What is the least possible total number of correct answers, summed over all children?')
q('bmo1-2007-q2','Geometry','Area & dissection',r'In a convex quadrilateral $ABCD$, points $M,N$ trisect $AB$ in that order, and points $P,Q$ trisect $CD$ in that order. Prove that both quadrilaterals $AMCP$ and $MNPQ$ have one third of the area of $ABCD$.')
q('bmo1-2007-q3','Combinatorics','Permutations & arrangements|Counting',r'How many nine-digit integers contain each digit $1,\ldots,9$ once, have the digits $1,2,3,4,5$ in that relative order, but do not have $1,2,3,4,5,6$ in that relative order?')
q('bmo1-2008-q1','Algebra','Algebraic identities',r'Evaluate $$\frac{1^4+2007^4+2008^4}{1^2+2007^2+2008^2}.$$')
q('bmo1-2008-q2','Number Theory','Diophantine equations|Divisibility & GCD',r'Find all positive integer triples satisfying $x+y-z=12$ and $x^2+y^2-z^2=12$.')
q('bmo2-2008-q2','Geometry','Triangle centres|Trigonometry',r'Triangle $ABC$ has incentre $I$ and circumcentre $O$, with $\angle AIO=90^\circ$ and $\angle CIO=45^\circ$. Determine $AB:BC:CA$.')
q('bmo2-2008-q3','Combinatorics','Logic & information|Algorithms & constructions|Combinatorial geometry',r'A circle in the coordinate plane contains the origin and has an integer radius between $1$ and $2008$. You may ask whether a chosen point $(x,y)$ lies inside the circle, receiving a truthful yes-or-no answer; points on the boundary may count as inside. Prove that its radius can always be determined using at most $60$ questions.')
q('bmo2-2008-q4','Number Theory','Diophantine equations|Divisibility & GCD|Infinite constructions',r'Prove that there are infinitely many pairs of distinct positive integers $x,y$ such that $x^3+y^2$ divides $x^2+y^3$.')
q('bmo1-2009-q2','Algebra','Equations & systems',r'Find all real triples satisfying $(x+1)yz=12$, $(y+1)zx=4$, and $(z+1)xy=4$.')
q('bmo2-2009-q4','Combinatorics','Digits & bases|Counting|Extremal arguments',r'Let $b(n)$ count the positive integers whose usual binary representations occur as consecutive blocks in the binary expansion of $n$. For example, $b(13)=6$, since $1101_2$ contains the representations of $1,2,3,5,6,13$. Prove that $n\le2500$ implies $b(n)\le39$, and find all cases of equality.')
q('bmo1-2010-q1','Number Theory','Diophantine equations|Squares & powers',r'Find all integer triples satisfying $x^2+y^2+z^2=2(yz+1)$ and $x+y+z=4018$.')
q('bmo1-2011-q1','Number Theory','Diophantine equations|Bounds & estimation',r'One integer is deleted from $\{1,2,\ldots,n\}$. The mean of the remaining integers is $40\tfrac34$. Which integer was deleted?')
q('bmo2-2011-q4','Combinatorics','Combinatorial geometry|Extremal arguments',r'Let $G=\{(x,y):x,y\in\mathbb Z,\ 1\le x,y\le2011\}$. What is the largest size of a subset of $G$ containing no four vertices of a proper parallelogram? A proper parallelogram has vertices not all on one line.')
q('bmo1-2012-q1','Number Theory','Diophantine equations|Squares & powers|Divisibility & GCD',r'Find all integers $n$ for which $n^2+20n+11$ is a perfect square, and prove that your list is complete.')
q('bmo1-2013-q2','Geometry','Circles & tangency|Angle chasing',r'Circles $S,T$ touch at $X$ and share a tangent touching them at distinct points $A,B$. If $AP$ is a diameter of $S$, prove that $B,X,P$ are collinear.')
q('bmo1-2013-q3','Algebra','Equations & systems|Algebraic identities',r'Find all real triples satisfying $x^2-4y+7=0$, $y^2-6z+14=0$, and $z^2-2x-7=0$.')
q('bmo1-2013-q5','Geometry','Area & dissection|Extremal arguments',r'A triangle has side lengths bounded above by $2,3,4$, respectively. Determine and prove its greatest possible area.')
q('bmo2-2013-q3','Combinatorics','Digits & bases|Counting|Binomial coefficients',r'Consider all positive integers whose binary expansions have exactly $2013$ digits and contain more zeros than ones. Let their number be $n$ and their sum be $s$. Prove that the binary expansion of $n+s$ also has more zeros than ones.')
q('bmo1-2014-q1','Algebra','Algebraic identities',r'Evaluate $$\frac{2014^4+4\cdot2013^4}{2013^2+4027^2}-\frac{2012^4+4\cdot2013^4}{2013^2+4025^2}.$$')
q('bmo2-2014-q3','Number Theory','Primes|Sequences & recurrences|Infinite constructions',r'Let $a_0=4$ and $a_n=a_{n-1}^2-a_{n-1}$ for $n\ge1$. (a) Prove that infinitely many primes divide at least one term. (b) Determine whether infinitely many primes divide no term.')
q('bmo2-2014-q4','Geometry','Triangle centres|Concurrency & collinearity|Inversion',r'Let $P$ be interior to triangle $ABC$. Lines $AP,BP,CP$ meet its circumcircle again at $A\prime,B\prime,C\prime$. Let $O_A,O_B,O_C$ be the circumcentres of $BCP,CAP,ABP$, and let $O_A\prime,O_B\prime,O_C\prime$ be the circumcentres of $B\prime C\prime P,C\prime A\prime P,A\prime B\prime P$. Prove that $O_AO_A\prime,O_BO_B\prime,O_CO_C\prime$ are concurrent.')
q('bmo1-2015-q1','Algebra','Bounds & estimation|Exponents & logarithms',r'Place $3^{3^4},3^{4^3},3^{4^4},4^{3^3},4^{3^4}$ in increasing order, with justification. Powers are associated to the right: $a^{b^c}=a^{(b^c)}$.')
q('bmo1-2015-q2','Number Theory','Primes|Divisibility & GCD|Squares & powers',r'Positive integers $p,a,b$ satisfy $p^2+a^2=b^2$. Prove that if $p>3$ is prime, then $12\mid a$ and $2(p+a+1)$ is a perfect square.')
q('bmo2-2015-q4','Combinatorics','Combinatorial geometry|Algorithms & constructions|Modular arithmetic',r'Two integer lattice points see each other if their joining segment contains no other lattice point. An $n$-loop consists of $n$ lattice points, no three collinear, such that precisely the consecutive pairs (including the last and first) see each other. Does a $100$-loop exist? Prove your answer.')
q('bmo2-2016-q2','Combinatorics','Logic & information|Extremal arguments',r'Alison has a hidden strict ranking of $20$ hockey teams. Benjamin may repeatedly name any three teams; Alison chooses whether to identify the strongest or the weakest of those three. Determine the greatest $N$ for which Benjamin can guarantee learning a chain of $N$ teams in their correct order, however Alison chooses her responses.')
q('bmo1-2017-q1','Combinatorics','Counting|Parity',r'Write all integers from $1$ to $2016$ in decimal, once each. Count the total number of appearances of odd digits in this list.')
q('bmo1-2017-q2','Algebra','Equations & systems|Functions & graphs',r'For $x>0$, define $g(x)=\max(x,1/x)$. Find all positive real $y$ satisfying $5y\,g(8y)\,g(25y)=1$.')
q('bmo1-2017-q3','Number Theory','Diophantine equations|Divisibility & GCD',r'Find all positive integer pairs $(m,n)$ for which $n^2-6n=m^2+m-10$.')
q('bmo2-2017-q4','Combinatorics','Logic & information|Games & strategies|Extremal arguments',r'A safe has an unknown three-digit code, with leading zeros allowed. A probe tests a proposed code and returns Fail if no digit is correct in its position, and Close otherwise, including when all three are correct. What is the smallest number of probe tests that guarantees identifying the code using an optimal strategy?')
q('bmo1-2018-q3','Geometry','Similarity & congruence|Area & dissection|Triangle geometry',r'Triangle $ABC$ has $AB=AC$ and longest side $BC$. Choose $N$ on $BC$ with $BN=AB$, and let $M$ be the perpendicular foot from $N$ to $AB$. Prove that $MN$ bisects both the area and the perimeter of the triangle.',r'Let $H$ be the midpoint of $BC$. The right triangles $BAH$ and $BNM$ have equal hypotenuses $AB=BN$ and the same angle at $B$, so they are congruent. Thus $BM=BH=BC/2$ and $MN=AH$. The area of $BMN$ is $BM\cdot MN/2=BC\cdot AH/4$, half the area of $ABC$. Its original-boundary portion has length $BM+BN=BC/2+AB$, half the perimeter of $ABC$.')
q('bmo2-2018-q4','Algebra','Functional equations|Functions & graphs|Sequences & recurrences',r'Call a real function $f:\mathbb R\to\mathbb R$ absorbing if it is nondecreasing and its $2018$th iterate $f^{2018}(z)$ is an integer for every real $z$. (a) Can such an $f$ take integer values at only finitely many real inputs? (b) Can there be such an $f$ and a strictly increasing sequence $a_1<a_2<\cdots$ such that $f(x)$ is an integer only when $x$ is one of the $a_i$? Iteration means repeated composition.')
q('bmo1-2020-q1','Number Theory','Primes|Modular arithmetic',r'Exhibit at least three primes $p<200$ for which $p+2,p+6,p+8,p+12$ are all prime. Prove also that there is exactly one prime $q$ for which $q+2,q+6,q+8,q+12,q+14$ are all prime.')
q('bmo2-2020-q3','Combinatorics','Colouring|Combinatorial geometry|Counting',r'Colour each cell of a $2019\times2019$ grid black or white. Call the colouring balanced if every contiguous $k\times k$ square subgrid, for every $1\le k\le2019$, has numbers of black and white cells differing by at most one. How many balanced colourings are there?')
q('bmo1-2021-q1','Algebra','Sequences & recurrences|Equations & systems',r'Alice first writes an integer $a$ with $-100\le a\le100$. Bob then writes twice her latest number, and on each later turn Alice writes Bob\'s latest number minus $45$; they continue alternating. Determine the possible $a$ for which $a$ appears again.',notes='Section A of the original paper required an answer only.')
q('bmo1-2021-q2','Geometry','Triangle geometry|Area & dissection|Diophantine equations',r'A triangle has side lengths $a,a,b$, perimeter $P$, and area $A$. Suppose $b,P$ are integers and $P=A^2$. Find every possible pair $(a,b)$.',notes='Section A of the original paper required an answer only.')
q('bmo1-2021-q4','Number Theory','Digits & bases|Squares & powers',r'Distinct decimal digits $A,B,C,D,E$ satisfy $$A^{\overline{AA}}+\overline{AA}=\overline{BBBCDEDBEEBBBBBE},$$ where the right-hand side is the sixteen-digit number written in grouped form $B,BBC,DED,BEE,BBB,BBE$, and $\overline{AA}$ is a two-digit number. Given $C=9$, determine $A,B,D,E$.',notes='Section A of the original paper required an answer only.')
q('bmo2-2021-q3','Geometry','Triangle centres|Circles & tangency|Concurrency & collinearity',r'Triangle $ABC$ has $AB>AC$, circumcircle $\Gamma$, and incentre $I$. The incircle touches $BC$ at $D$. Let $K$ lie on $\Gamma$ with $\angle AKI=90^\circ$. Prove that $AI$ and $KD$ intersect on $\Gamma$.')
q('bmo2-2021-q4','Combinatorics','Permutations & arrangements|Algorithms & constructions|Recurrences & generating functions',r'Define a sequence of positive integers greedily: $a_n$ is the smallest positive integer not previously used for which the mean of $a_1,\ldots,a_n$ is an integer. Prove that the sequence $a_i-i$, for $i\ge1$, contains each integer exactly once.')
q('bmo2-2022-q3','Combinatorics','Pigeonhole principle|Sets & partitions|Extremal arguments',r'Place the cards from $n$ identical decks in boxes, each holding at most $2022$ cards. Each deck has one card of each label $1,\ldots,50$. A pile of boxes is regular if it contains equally many cards of every label. Prove that some $N$ exists such that, whenever $n\ge N$, the boxes can be split into two nonempty regular piles.')
q('bmo2-2022-q4','Geometry','Coordinates & vectors|Concurrency & collinearity|Circles & tangency',r'Let $ABC$ be acute with circumcircle $\Gamma$. Let $\ell_B,\ell_C$ pass through $B,C$, respectively, perpendicular to $BC$. For $T$ on the minor arc $BC$, its tangent to $\Gamma$ meets these lines at $P_B,P_C$. The perpendicular to $AC$ through $P_B$ and the perpendicular to $AB$ through $P_C$ meet at $Q$. If $Q$ lies on $BC$, prove that $A,T,Q$ are collinear.')
q('bmo1-2023-q1','Number Theory','Digits & bases|Divisibility & GCD',r'Houses on a road are numbered from $1$ to a three-digit integer $n$. Exactly $1/k$ of these numbers begin with digit $2$, for some positive integer $k$. Find all possible $n$.')
q('bmo1-2024-q2','Algebra','Sequences & recurrences|Invariants',r'An integer sequence satisfies $a_i\in\{2a_{i-1}-a_{i-2},\ 2a_{i-2}-a_{i-1}\}$ for every $i\ge2$. If $a_{2023},a_{2024}$ are consecutive integers, prove that $a_0,a_1$ are consecutive integers, in either order.')
q('bmo1-2025-q3','Combinatorics','Games & strategies|Parity',r'Initially $10^6$ is on a board. A move replaces the current number $n$ by $|a-b|$, where $a,b$ are distinct positive integers with $ab=n$. Rhian moves first, and she and Jack then alternate; a player unable to move loses. Determine who can force a win.')
q('bmo2-2026-q4','Algebra','Sequences & recurrences|Extremal arguments',r'Fix a positive integer $N$ and a sequence of integers $1\le k_n\le N$. Choose arbitrary integers $x_1,\ldots,x_N$ and, for $n>N$, define $$x_n=\sum_{i=n-k_n}^{n-1}x_i.$$ Prove that the resulting infinite sequence has either only finitely many strictly positive terms or only finitely many strictly negative terms.')
# Historical papers, including their original advanced geometry/mechanics tasks.
q('bmo-1973-q1','Geometry','Circles & tangency|Projective geometry & conics',r'A variable circle touches two fixed circles at $P,Q$. Prove that $PQ$ passes through one of two fixed points. State a true generalisation to ellipses, or more general conics, having this result as a special case.',notes='The requested conic generalisation is part of the original task.')
q('bmo-1973-q2','Combinatorics','Pigeonhole principle|Combinatorial geometry',r'Nine points lie in the interior of a unit square. Prove that some three are the vertices of a triangle of area less than $1/8$.')
q('bmo-1973-q3','Geometry','Solid geometry|Trigonometry|Geometric inequalities',r'Rotate the quarter-circle $x^2+y^2=r^2$, $x,y\ge0$, together with the segment $x=r$, $-h\le y\le0$, about the $y$-axis. This produces a hemisphere on a cylinder. A string is stretched tightly over the surface from $(r\sin\theta,r\cos\theta)$ on the original meridian to $(-r,-h)$ in the same meridian plane. Prove that the string is not contained in a plane if $\tan\theta>r/h$. Standard spherical triangle formulae may be used.',notes='Historical problem requiring surface geodesics and spherical trigonometry.')
q('bmo-1973-q4','Geometry','Combinatorial geometry|Quadrilaterals & polygons|Area & dissection',r'Determine which positive integers $n$ allow $n$ congruent equilateral triangular tiles to fit together without overlap or gaps into a convex hexagon whose six interior angles are $120^\circ$. The first three possible values are $6,10,13$.')
q('bmo-1973-q6','Combinatorics','Probability|Counting',r'For a yes-or-no question, a teacher answers correctly with probability $\alpha$; a boy does so with probability $\beta$ and a girl with probability $\gamma$. A uniformly selected pupil agrees with the teacher with probability $1/2$. Under the independent-answer model, determine the ratio of boys to girls, including parameter values for which the ratio is not determined.',notes='The original wording implicitly uses independent correctness of teacher and pupil. This assumption and its degenerate cases are made explicit here; marginal correctness probabilities alone do not determine agreement.')
q('bmo-1973-q11','Algebra','Calculus & modelling|Trigonometry',r'''Uniform rough cylinders $A,B$ of equal length have radii $a,b$ and masses $M,m$. Cylinder $A$ rests on a rough horizontal table, and $B$ initially balances directly above it. After a disturbance, $B$ rolls on $A$ while $A$ rolls on the table. Let $\theta$ be the angle between the vertical and the plane containing their axes.

(i) For the motion without slipping, draw force and angle diagrams, state the mechanical principles, and give equations that can be reduced to a differential equation for $\theta$. Explain the elimination without carrying it out.

(ii) With $k=M/m$, the resulting equation is
$$\ddot\theta\left(4+2\cos\theta-2\cos^2\theta+\frac{9k}{2}\right)+\dot\theta^2\sin\theta(2\cos\theta-1)=\frac{3g(1+k)\sin\theta}{a+b}.$$
Obtain $\dot\theta$ in terms of $\theta$. You may use the axial moment of inertia $\tfrac12\times\text{mass}\times\text{radius}^2$.''',notes='Historical mechanics question; rotational dynamics and differential equations are required.')
q('bmo-1974-qA1','Algebra','Calculus & modelling|Functions & graphs',r'In the first quadrant, curve $A$ is $y=\frac43x^2$ and curve $C$ is $y=\frac38x^2$. An increasing curve $B$ runs from the origin between them. For every point $P$ on $B$, the region bounded by $A$, $B$, and the horizontal segment from $P$ to $A$ has the same area as the region bounded by $B$, $C$, and the vertical segment from $P$ to $C$. Find the equation of $B$.',notes='The two regions in the official diagram are specified verbally here.')
q('bmo-1974-qA3','Combinatorics','Graph theory|Double counting',r'Prove that no convex polyhedron can have all of its faces hexagons.')
q('bmo-1974-qB9','Algebra','Calculus & modelling',r'A uniform rod of length $2a$ is hinged at its lower end to a frictionless joint on a horizontal table. It is initially vertical and at rest in unstable equilibrium. Find the time it takes to fall onto the table, and comment on the result. You may use $\int\csc x\,dx=\log|\tan(x/2)|$.',notes='Historical mechanics problem. The requested comment includes the issue of starting exactly at the unstable equilibrium.')
q('bmo-1974-qB10','Algebra','Calculus & modelling|Trigonometry',r'A solid right circular cone has vertex $V$, height $h$, semi-vertical angle $\alpha$, and uniform density. Remove the points at distance less than $a$ or greater than $b$ from $V$, where $0<a<b<h$, leaving mass $M$. Using the inverse-square gravitational law with constant $G$, prove that its attraction on a unit mass at $V$ has magnitude $$\frac{3GM(1+\cos\alpha)}{2(a^2+ab+b^2)}.$$')
q('bmo-1975-q2','Number Theory','Primes|Divisibility & GCD',r'Partition the first $n$ primes into disjoint sets $A=\{a_1,\ldots,a_h\}$ and $B=\{b_1,\ldots,b_k\}$. Choose arbitrary positive integer exponents $\alpha_i,\beta_j$, and form $U=\prod_i a_i^{\alpha_i}$ and $V=\prod_j b_j^{\beta_j}$. Prove that every positive divisor $d$ of $U-V$ is either $1$ or greater than the $n$th prime.')
q('bmo-1975-q7','Algebra','Inequalities|Equations & systems',r'Prove that for each positive integer $n$ there is exactly one real tuple $(x_1,\ldots,x_n)$ satisfying $$(1-x_1)^2+(x_1-x_2)^2+\cdots+(x_{n-1}-x_n)^2+x_n^2=\frac1{n+1}.$$')
q('bmo-1976-q2','Algebra','Inequalities',r'For positive real numbers $x,y,z$, prove $$\frac{x}{y+z}+\frac{y}{z+x}+\frac{z}{x+y}\ge\frac32.$$')
q('bmo-1976-q6','Geometry','Solid geometry|Trigonometry|Geometric inequalities',r'A sphere of radius $r$ and centre $O$ is cut by a horizontal plane $r/2$ above $O$, meeting it in circle $K$. Replace the upper cap with a cone of base $K$ and vertex $V$ at height $2r$ above $O$. Let $Q$ lie on the sphere at the height of $O$. The plane $OVQ$ meets $K$ at $X,Y$, with $Y$ farther from $Q$. A point $P$ on $VY$ is chosen so that the shortest surface path from $P$ to $Q$ crosses $K$ at $45^\circ$. Prove $$VP=\frac{\sqrt3\,r}{\sqrt{1+1/\sqrt5}}.$$ Standard spherical sine and cosine rules may be used.')
q('bmo-1977-q1','Number Theory','Arithmetic functions|Primes|Digits & bases',r'A function $f$ assigns a nonnegative integer to each positive integer, with $f(mn)=f(m)+f(n)$ for all $m,n$, $f(10)=0$, and $f(n)=0$ whenever the final decimal digit of $n$ is $3$. Prove that $f(n)=0$ for every positive integer $n$.')
q('bmo-1981-q3','Algebra','Inequalities',r'For positive real numbers $a,b,c$, prove both $$a^3+b^3+c^3\ge a^2b+b^2c+c^2a$$ and $$abc\ge(a+b-c)(b+c-a)(c+a-b).$$')
q('bmo-1982-q5','Geometry','Solid geometry|Projective geometry & conics|Geometric inequalities',r'A right circular cone stands on a horizontal base of radius $r$ and has slant height $\ell$. A plane cuts it in an ellipse, with lowest and highest points $L,H$. On one side of plane $VLH$, consider the half-ellipse route from $L$ to $H$ and the shortest route on the cone surface. Find the condition under which these two routes intersect at a point strictly between $L$ and $H$.')
q('bmo-1983-q4','Geometry','Solid geometry|Geometric inequalities',r'The cylindrical surfaces $x^2+z^2=a^2$, $z\ge0$, $|y|\le a$, and $y^2+z^2=a^2$, $z\ge0$, $|x|\le a$, together with $z=0$, enclose a cupola. It sits on a vertical tower of height $h$ and square cross-section of side $2a$. Find the shortest path over the cupola and tower surfaces from the highest point of the cupola to a corner of the tower base.')
q('bmo-1985-q2','Algebra','Inequalities',r'If $0<a,b,c<1$, prove that $a(1-b)$, $b(1-c)$, and $c(1-a)$ cannot all exceed $1/4$.')
q('bmo-1986-q1','Number Theory','Divisibility & GCD',r'Reduce the fraction $$\frac{2244851485148514627}{8118811881188118000}$$ to its lowest terms.')
q('bmo-1989-q1','Algebra','Polynomials|Equations & systems',r'Find all integers $a,b,c$ for which $(x-a)(x-10)+1=(x+b)(x+c)$ for every real $x$.')
q('bmo-1989-q2','Geometry','Coordinates & vectors|Triangle centres',r'In triangle $ABC$, put $b=AC$ and $c=AB$. Let $P\ne A$ lie on line $AB$, and $Q\ne A$ on line $AC$. Write $x=AP$, $y=AQ$ as directed lengths, positive in the directions from $A$ toward $B,C$. Prove that $PQ$ passes through the centroid if and only if $3xy=bx+cy$.')
q('bmo-1989-q5','Algebra','Trigonometry|Inequalities',r'No angle of triangle $ABC$ exceeds $90^\circ$. Prove that $\sin A+\sin B+\sin C>2$.')
q('bmo-1990-q1','Number Theory','Digits & bases',r'Find a positive integer beginning with digit $1$ such that moving that first digit to the end triples the number.')
q('bmo-1991-q1','Number Theory','Modular arithmetic|Squares & powers',r'Prove that $3^n+2\cdot17^n$ is never a perfect square for a nonnegative integer $n$.')
q('fist-1975-q4','Geometry','Solid geometry|Circles & tangency|Constructions & loci',r'''Prove that twelve circles of equal radius can be placed on a sphere with the following tangencies, and no others. Label them $A_i,B_i,C_i$ for $i=1,2,3,4$, reading indices modulo $4$:

- $A_i$ touches $A_{i-1},A_{i+1},B_{i-1},B_i,C_i$;
- $B_i$ touches $A_i,A_{i+1},C_i,C_{i+1}$;
- $C_i$ touches $A_i,B_{i-1},B_i$.

Thus four circles each touch five others, four each touch four, and four each touch three.''',notes='The adjacency list explicitly transcribes the twelve-circle tangency diagram in the original paper.')
q('fist-1976-q1','Geometry','Coordinates & vectors|Triangle geometry',r'For an interior point $P$ of a fixed triangle $ABC$, draw through $P$ lines parallel to the medians from $A,B,C$, meeting $BC,CA,AB$ at $L,M,N$, respectively. Prove that $BL/BC+CM/CA+AN/AB$ is independent of $P$.')
q('fist-1977-q3a','Number Theory','Diophantine equations|Divisibility & GCD',r'Prove that for every integer $n$, the equation $10xy+17yz+27zx=n$ has an integer solution $(x,y,z)$.',notes='The original paper offered this as alternative (a) to question 3(b).')
q('fist-1977-q3b','Number Theory','Primes|Sequences & recurrences',r'For positive integers $a,d$, prove that the progression $a,a+d,a+2d,\ldots$ contains infinitely many terms with exactly the same prime divisors.',notes='The original paper offered this as alternative (b) to question 3(a).')
q('fist-1980-q4','Combinatorics','Graph theory|Algorithms & constructions',r'For a set of $n$ people, arrange a series of bridge games so that every pair of people are opponents in exactly one game. A game has four players in two partnerships; repeated partnerships are allowed. Prove that this can be done precisely when $n=8m+1$ for a positive integer $m$.',notes='As in the original nontrivial bridge schedule, at least one game is required; the empty schedule for one person is not intended.')
q('fist-1981-q2','Geometry','Solid geometry|Transformations|Symmetry',r'An axis of a solid is a line about which some rotation strictly between $0^\circ$ and $360^\circ$ maps the solid onto itself. How many axes does a cube have? Draw its three types of axis, state the least positive rotation angle for each type, and label the eight vertices to show the induced permutation. Formal proofs are not required.')
q('fist-1981-q4','Algebra','Polynomials|Algebraic identities',r'Find the remainder when $x^{81}+x^{49}+x^{25}+x^9+x$ is divided by $x^3-x$.')
q('fist-1983-qG1','Geometry','Coordinates & vectors|Geometric inequalities',r'Points $A,B$ and a line $k$ are fixed in a plane. For a variable point $P$, let $N$ be its perpendicular foot on $k$. Locate and prove the position of $P$ minimising $PA^2+PB^2+PN^2$. State, without proof, the corresponding generalisation for three fixed points $A,B,C$ and the expression $PA^2+PB^2+PC^2+PN^2$.')
q('fist-1988-q6','Algebra','Inequalities',r'The triples $(a_1,b_1,c_1)$ and $(a_2,b_2,c_2)$ are side lengths of triangles. Prove that $\sqrt{a_1^2+a_2^2}$, $\sqrt{b_1^2+b_2^2}$, $\sqrt{c_1^2+c_2^2}$ are also side lengths of a triangle.')

# Normalize labels to the site's common subtopic vocabulary.
label_aliases={'Angle chasing':'Angles & cyclic quadrilaterals','Infinite constructions':'Algorithms & constructions','Bounds & estimation':'Inequalities','Exponents & logarithms':'Squares & powers','Telescoping':'Sequences & recurrences','Counterexamples':'Inequalities','Inversion':'Transformations','Binomial coefficients':'Counting'}
for row in restored:
 row['subtopics']=list(dict.fromkeys(label_aliases.get(s,s) for s in row['subtopics']))
 for field in ['statement','ratingReason','notes','solution']:
  if isinstance(row.get(field),str):row[field]=row[field].replace("\\'", "'")

# One old transcription accidentally changed the geometry construction.
corrected_statement=r'Let $X,Y$ be the perpendicular feet from a point $P$ to the lines $CA,CB$ of triangle $ABC$, with $PX=PY$. The line through $P$ perpendicular to $AB$ meets $XY$ at $Z$. Prove that $CZ$ bisects $AB$.'
corrected_reason='The equal distances put P on an angle bisector at C. Coordinates along that bisector make XY a line of constant first coordinate; the perpendicular condition then identifies CZ as the median. The construction must be followed carefully, but the resulting calculation is short.'
corrected_solution=r'''Choose coordinates $C=(0,0)$ and $P=(p,0)$. Since $P$ is equidistant from the two side lines, write $A=(a,ta)$ and $B=(b,-tb)$, allowing signed $a,b$ to cover both angle bisectors. The perpendicular feet have first coordinate $p/(1+t^2)$, so $Z=(p/(1+t^2),z)$.

The direction of $AB$ is $(b-a,-t(a+b))$. Since $PZ\perp AB$,
$$(b-a)\left(\frac{p}{1+t^2}-p\right)-t(a+b)z=0,$$
whence
$$Z=\frac{p}{(1+t^2)(a+b)}\,(a+b,t(a-b)).$$
The midpoint of $AB$ is $((a+b)/2,t(a-b)/2)$, proving the required collinearity with $C$. The nondegeneracy implicit in the defined intersection $Z$ rules out the zero denominators.'''
byid={row['id']:row for row in rows}
for row in restored:byid[row['id']]=row
fix=byid['bmo-1974-qB6']
fix.update(statement=corrected_statement,difficulty=4.5,ratingReason=corrected_reason,solution=corrected_solution,solutionKind='original-exposition',solutionCredit='Independent mathematical exposition for Olympiad Atlas',subtopics=['Coordinates & vectors','Triangle geometry','Concurrency & collinearity'])
fix['notes']='Corrected against the official 1974 scan: the perpendicular through P meets XY at Z, and CZ bisects AB. An earlier bank transcription incorrectly introduced an extra point Q and changed the conclusion. Reassessed from the corrected problem.'
for item in cov['historicalScreening']:
 if item['year']==1974 and item['competition']=='BMO' and item['number']=='B6':item.update(difficulty=4.5,reason=corrected_reason)
for ident,row in byid.items():
 review=lookup.get(ident)
 if review:review['decision']='include'
for paper in cov['papers']:
 paper['includedCount']=sum(p['competition']==paper['competition'] and p['year']==paper['archiveYear'] for p in byid.values())
cov['counts'].update(included=len(byid),excluded=sum(x['decision']=='exclude' for x in cov['screening']+cov['historicalScreening']),withOwnWorkedSolution=sum(bool(p.get('solution')) for p in byid.values()),withOfficialSolutionLink=sum(bool(p.get('solutionUrl')) for p in byid.values()))
cov['preferredDifficultyRange']=[4,7]
cov['publicationPolicy']='All individually assessed questions with verified usable statements are published, regardless of difficulty. Ratings 4–7 are a browsing preference only. BMO1973 Q9 remains held for missing nondegeneracy hypotheses.'
audit=cov.setdefault('sourceAudit',{})
audit['allRatingsRestoration']='110 previously omitted British questions restored from official papers with individually checked mathematical paraphrases and subtopics. The 107-paper archive has 552 numeric assessments and 551 usable published statements; BMO1973 Q9 is held as under-specified.'
audit['corrections']=[x for x in audit.get('corrections',[]) if x.get('id')!='bmo-1974-qB6']+[dict(id='bmo-1974-qB6',previousDifficulty=6,difficulty=4.5,detail='Restored the actual perpendicular-line construction and CZ midpoint conclusion from the official scan; replaced the rating rationale and supplied a verified coordinate solution.')]
rows=sorted(byid.values(),key=lambda x:(x['year'],x['competition'],str(x['number'])))
assert len(rows)==551 and len({p['id'] for p in restored})==110
assert all(p['difficulty']==lookup[p['id']]['difficulty'] for p in rows)
(R/'data/british.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
(R/'research/british-coverage.json').write_text(json.dumps(cov,ensure_ascii=False,indent=2)+'\n')
(R/'research/british-restored-records.json').write_text(json.dumps(restored,ensure_ascii=False,indent=2)+'\n')
(R/'research/british-historic-records.json').write_text(json.dumps([p for p in rows if p['competition'] in ['BMO','FIST']],ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'restored':len(restored),'published':len(rows),'held':['bmo-1973-q9'],'numericAssessments':len(lookup)}))
